/* Evidence only: preserve the failed exact-hash gate in workbenches.cjs. */
const fs=require('node:fs'),path=require('node:path'),zlib=require('node:zlib'),crypto=require('node:crypto'),{webkit}=require('playwright');
const out=path.resolve('qa-output/numeric-diagnostic');fs.mkdirSync(out,{recursive:true});
const cases=JSON.parse(fs.readFileSync('research/neck-runtime-probe-report.json')).caseRows;
const meta=JSON.parse(fs.readFileSync('frozen/neck-cotangent.json')),raw=zlib.gunzipSync(fs.readFileSync('frozen/neck-cotangent.bin.gz')),ab=raw.buffer.slice(raw.byteOffset,raw.byteOffset+raw.byteLength),n=meta.unknownCount,b=meta.boundaryCount,U=new Uint32Array(ab,0,n),B=new Uint32Array(ab,n*4,b),W=new Float32Array(ab,(n+b)*4,n*b),mask=new Set(U),boundary=new Set(B);
function read(f){const r=fs.readFileSync(f);return new Float32Array(r.buffer.slice(r.byteOffset,r.byteOffset+r.byteLength));}
function hash(a){return crypto.createHash('sha256').update(a).digest('hex');}
function apply(p){const v=p.slice();for(let i=0;i<n;i++)for(let k=0;k<3;k++){let q=0;for(let j=0;j<b;j++)q+=W[i*b+j]*p[B[j]*3+k];v[U[i]*3+k]=q;}return v;}
function diff(a,b){let sum=0,max=0,count=0,inside=0,outside=0,bd=0;const affected=new Set(),top=[];for(let k=0;k<a.length;k++){const d=Math.abs(a[k]-b[k]);sum+=d*d;if(d){count++;const v=Math.floor(k/3);affected.add(v);if(mask.has(v))inside++;else outside++;if(boundary.has(v))bd++;if(d>max)max=d;top.push({vertex:v,axis:k%3,actual:a[k],expected:b[k],deltaMM:d*1000});}}top.sort((a,b)=>b.deltaMM-a.deltaMM);return{actualSHA256:hash(a),expectedSHA256:hash(b),exact:count===0,differentCoordinates:count,differentVertices:affected.size,insideCoordinates:inside,outsideCoordinates:outside,boundaryCoordinates:bd,maxAbsMM:max*1000,rmsCoordinateMM:Math.sqrt(sum/a.length)*1000,top:top.slice(0,12)};}
(async()=>{const browser=await webkit.launch({headless:true}),baseline={},rows=[],errors=[];for(const folder of ['baseline','candidate']){const c=await browser.newContext({viewport:{width:1440,height:1100}}),page=await c.newPage();page.on('pageerror',e=>errors.push(e.message));await page.goto(`http://127.0.0.1:8765/${folder}/kaopu-skin-workbench/?local=1`);await page.waitForFunction(()=>window.unifiedWorkbench?.diagnostics().ready,null,{timeout:180000});for(const row of cases){await page.evaluate(s=>window.unifiedWorkbench.setState(s),row.state);const p=Float32Array.from(await page.evaluate(()=>Array.from(window.unifiedWorkbench.positions())));fs.writeFileSync(path.join(out,folder+'-'+row.name+'.bin'),p);if(folder==='baseline'){baseline[row.name]=p;continue;}const old=baseline[row.name],nodeOld=read('research/baseline-cases/'+row.name+'-vertices.bin'),nodeNew=read('research/candidate-cases/'+row.name+'-vertices.bin');const repeated=Float32Array.from(await page.evaluate(s=>{window.unifiedWorkbench.setState(s);return Array.from(window.unifiedWorkbench.positions())},row.state));rows.push({case:row.name,baselineVsNode:diff(old,nodeOld),runtimeVsNode:diff(p,nodeNew),runtimeVsNodeOperatorOnBrowserInput:diff(p,apply(old)),repeat:diff(p,repeated),outsideChangedByRepair:Array.from(p).some((v,k)=>!mask.has(Math.floor(k/3))&&v!==old[k])});fs.writeFileSync(path.join(out,'evidence.json'),JSON.stringify({evidenceOnly:true,priorExactGateStillFailed:true,engine:'webkit',version:browser.version(),rows,errors},null,2));}await c.close();}await browser.close();console.log(JSON.stringify(rows.map(r=>({case:r.case,input:r.baselineVsNode.maxAbsMM,output:r.runtimeVsNode.maxAbsMM,operator:r.runtimeVsNodeOperatorOnBrowserInput.maxAbsMM,repeat:r.repeat.exact,outside:r.outsideChangedByRepair}))));})().catch(e=>{fs.writeFileSync(path.join(out,'failure.txt'),String(e.stack||e));console.error(e);process.exit(1)});
